#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

void* detached_thread_func(void* arg) {
    printf("Detached thread running. Will exit soon.\n");
    /* Resources will be cleaned up automatically */
    return NULL;
}

int main() {
    pthread_attr_t attr;
    pthread_t thread_id;
    int s;
    int current_state;

    /* 1. Initialize attributes object */
    s = pthread_attr_init(&attr);
    if (s != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", s);
        return 1;
    }

    /* 2. Set the detach state to detached */
    s = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
    if (s != 0) {
        fprintf(stderr, "Error setting detach state: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    /* 3. Verify the setting */
    s = pthread_attr_getdetachstate(&attr, &current_state);
    if (s == 0) {
        if (current_state == PTHREAD_CREATE_DETACHED) {
            printf("Attribute set successfully to DETACHED.\n");
        } else {
            printf("Attribute retrieval failed verification.\n");
        }
    }

    /* 4. Create the thread using the detached attributes */
    s = pthread_create(&thread_id, &attr, detached_thread_func, NULL);
    if (s != 0) {
        fprintf(stderr, "Error creating thread: %d\n", s);
        pthread_attr_destroy(&attr);
        return 1;
    }

    /* 5. Clean up the attributes object (it's no longer needed) */
    pthread_attr_destroy(&attr);

    /* Attempting to join this thread would result in an error (e.g., ESRCH or EINVAL) */
    /* Since the thread is detached, we just allow main to exit */

    printf("Main thread exiting.\n");
    pthread_exit(NULL); /* Use pthread_exit to allow other threads time to finish */
}
